{
  "name": "mm_sec_machwkey_write",
  "confidence": "medium",
  "docstring": "Writes a received WiFi pairwise or group key into the MAC security hardware key context, selecting the programming path from the message security-mode field.",
  "subsystem": "mm",
  "var_renames": {
    "a1": "sec_key_msg",
    "v1": "key_index",
    "v2": "sta_index"
  },
  "struct_hints": [
    {
      "offset": 1,
      "meaning": "key index; 0xFF indicates a GTK and other values identify pairwise key slots"
    },
    {
      "offset": 40,
      "meaning": "security/cipher mode used to choose the key programming path"
    },
    {
      "offset": 41,
      "meaning": "station index associated with the key"
    },
    {
      "offset": 8,
      "meaning": "start of the first 16-byte key material copied into off_118C6C"
    },
    {
      "offset": 24,
      "meaning": "start of an optional second 16-byte key material field used by some cipher modes"
    }
  ]
}
